"""Strengthen the unexecuted assurance candidate; preserve its first version."""
from pathlib import Path
p=Path(__file__).resolve().parent
s=(p/'assure.py').read_text()
s=s.replace("from allocate_real import allocate_inventory,text_tensor,layer_of", "from allocate_real import allocate_inventory,text_tensor,layer_of,nbytes")
s=s.replace("require(gate['passed'] and len(gate['cases'])==3,'small gate')", "require(gate['passed'] and [x['length'] for x in gate['cases']]==[17,64,256],'small gate exact case coverage')\n    require(all([y['layer'] for y in x['per_layer_hidden']]==list(range(24)) and x['capture_witness_vs_pristine']['max_abs_diff']==0 and x['compute_dtype']=='mlx.core.bfloat16' for x in gate['cases']),'small exact hidden/witness coverage')")
s=s.replace("c['actual_token_digests_verified']=True", "require(sens['data']=={k:v for k,v in train.items() if k!='tokens'},'calibration actual population metadata')\n    c['actual_token_digests_verified']=True")
s=s.replace("require(not e['checkpoint']['missing'],name+' loaded tensor coverage')", "require(math.isclose(sum(r['nll_sum'] for r in e['sequences']),e['nll_sum'],abs_tol=1e-8),name+' NLL per-sequence sum')\n        require(not e['checkpoint']['missing'],name+' loaded tensor coverage')")
s=s.replace("actual=scan_checkpoint(pathlib.Path(cp['path']))", "actual=scan_checkpoint(pathlib.Path(cp['path']))\n        require(actual==inv[name]['tensors'],name+' actual inventory exact header binding')\n        require(sha(pathlib.Path(cp['path'])/'config.json')==cp['config_sha256'],name+' actual config digest')\n        for tensor,h in source_hashes[name].items():require(hash_range(actual[tensor])==h,name+' actual source bytes '+tensor)")
s=s.replace("for tensor,record in m['tensors'].items():", "actual=scan_checkpoint(pathlib.Path(cp['path']));cfg=read('checkpoint-'+name+'/config.json')\n        require(sha(pathlib.Path(cp['path'])/'config.json')==cp['config_sha256'],name+' mixed loaded config digest')\n        require(sum(nbytes(v) for v in actual.values())==m['text_stored_bytes']==plans['plans'][idx]['text_stored_bytes'],name+' actual stored bytes')\n        baseline=sum(nbytes(v) for n,v in inv['q4']['tensors'].items() if text_tensor(n))\n        require(baseline-m['text_stored_bytes']==m['actual_saved_bytes'],name+' actual savings')\n        modules={n[:-7] for n in actual if n.endswith('.scales')}\n        overrides=cfg['quantization']\n        require(set(overrides)==modules|{'bits','group_size','mode'},name+' exact override module set')\n        require(cfg['text_config']['quantization']==overrides,name+' nested overrides')\n        for module in modules:\n            bits=3 if layer_of(module) in m['q3_layers'] else 4\n            require(overrides[module]=={'bits':bits,'group_size':64,'mode':'affine'},name+' explicit quant interpretation '+module)\n        for tensor,record in m['tensors'].items():\n            require(hash_range(actual[tensor])==record['sha256'],name+' actual mixed bytes '+tensor)\n            require(all(actual[tensor][k]==record[k] for k in ['shape','dtype','start','end']),name+' actual mixed metadata '+tensor)")
s=s.replace("require(all(x['pressure'] in (1,2) and x['rss_bytes']<3*2**30 for x in samples),name+' guard samples')", "require(bool(samples) and all(x['pressure'] in (1,2) and x['rss_bytes']<3*2**30 for x in samples),name+' guard samples')\n        timestamps=[rows[0]['time']]+[x['time'] for x in samples]+[rows[-1]['time']]\n        require(all(0<=b-a<=8 for a,b in zip(timestamps,timestamps[1:])),name+' observation gaps')")
s=s.replace("verdict['passed']=True", "trusted=read('trusted-deployment-v2.json')\n    for name,h in trusted.items():require(sha(ROOT/name)==h,'deployment-source/data equality '+name)\n    verdict['trusted_deployment_files_checked']=len(trusted)\n    verdict['passed']=True")
with (p/'assure_v2.py').open('x') as f:f.write(s)
